function getTenableTranslation(key, lang) {
    return (tenableTranslations[lang] && tenableTranslations[lang][key]) ||
           (tenableTranslations.en && tenableTranslations.en[key]) || null;
}

function applyTenableTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.tenable.") || key.startsWith("review.common."))) {
            const translation = getTenableTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyTenableTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyTenableTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyTenableTranslations(window.i18n?.getCurrentLanguage() || "en");
}
